124	        }
125	
126	        const name = params.name ?? id;
127	
128	        // Strip embedded credentials from the URL before storing.
129	        let cleanUrl = params.url;
130	        let credentialsWereStripped = false;
131	        if (hasEmbeddedCredentials(params.url)) {
132	            cleanUrl = stripEmbeddedCredentials(params.url);
133	            credentialsWereStripped = true;
134	        }
135	
136	        const duplicate = store.Repositories.find((r) => r.Id === id);
137	        if (duplicate) {
138	            throw new Error(
139	                `A repository with ID "${id}" already exists.`
140	            );
141	        }
142	
143	        const duplicateUrl = store.Repositories.find((r) => r.Url === cleanUrl);
144	        if (duplicateUrl) {
145	            throw new Error(
146	                `A repository with URL "${redactUrl(cleanUrl)}" already exists (ID: "${duplicateUrl.Id}").`
147	            );
148	        }
149	
150	        const repo: Repository = { Id: id, Name: name, Url: cleanUrl };
151	        store.Repositories.push(repo);
152	        this.save(store);
153	
154	        if (credentialsWereStripped) {
155	            return { ...repo, credentialsStripped: true };
156	        }
